mapper.select:
SELECT kb.id, kb.name, kb.description, kb.embedding_model_id AS "embeddingModelId", em.name AS "embeddingModelName", kb.rerank_enabled AS "rerankEnabled", kb.rerank_model_id AS "rerankModelId", kb.retrieval_mode AS "retrievalMode", kb.top_k AS "topK", kb.score_threshold AS "scoreThreshold", kb.vector_weight AS "vectorWeight", kb.bm25_weight AS "bm25Weight", kb.owner_id AS "ownerId", u.username AS "ownerName", kb.visibility, kb.status, kb.doc_count AS "docCount", kb.chunk_count AS "chunkCount", kb.created_at AS "createdAt", kb.updated_at AS "updatedAt" FROM kb_knowledge_base kb JOIN llm_model em ON em.id = kb.embedding_model_id JOIN sys_user u ON u.id = kb.owner_id
AND kb.name ILIKE '%' || #{keyword} || '%' AND kb.status = #{status} AND kb.owner_id = #{ownerId}
ORDER BY kb.updated_at DESC, kb.id DESC

mapper.update:
UPDATE kb_knowledge_base
name = #{name}, description = #{description}, embedding_model_id = #{embeddingModelId}, rerank_model_id = #{rerankModelId}, chunk_size = #{chunkSize}, chunk_overlap = #{chunkOverlap}, separators = CAST(#{separators} AS jsonb), retrieval_mode = #{retrievalMode}, vector_weight = #{vectorWeight}, bm25_weight = #{bm25Weight}, top_k = #{topK}, score_threshold = #{scoreThreshold}, rerank_enabled = #{rerankEnabled}, visibility = #{visibility}, id = id,
WHERE id = #{id}
